style.css:
/* Tema Verde Oscuro para Pinterest */
/* Colores principales: Verde oscuro, verde claro y gris */

/* Fondo de la página */
body {
    background-color: #1a2e1a !important; /* Verde oscuro */
}

/* Barra superior */
[data-test-id="header"] {
    background-color: #0d1a0d !important; /* Verde más oscuro */
    border-bottom: 1px solid #2d4d2d !important;
}

/* Tarjetas de pins */
[data-test-id="pin"] {
    background-color: #2d4d2d !important; /* Verde medio */
    border-radius: 12px !important;
    border: 1px solid #3b6b3b !important;
}

/* Texto en las tarjetas */
[data-test-id="pin"] h3,
[data-test-id="pin"] p {
    color: #e0f2e0 !important; /* Verde claro para el texto */
}

/* Botones */
button {
    background-color: #3b6b3b !important; /* Verde oscuro */
    color: #e0f2e0 !important; /* Verde claro */
    border: none !important;
    border-radius: 8px !important;
}

/* Hover en botones */
button:hover {
    background-color: #4d7a4d !important; /* Verde más claro */
}

/* Barra de búsqueda */
[data-test-id="search-box-input"] {
    background-color: #2d4d2d !important; /* Verde medio */
    color: #e0f2e0 !important; /* Verde claro */
    border: 1px solid #3b6b3b !important;
}

/* Iconos */
svg {
    fill: #e0f2e0 !important; /* Verde claro para iconos */
}

/* Footer */
footer {
    background-color: #0d1a0d !important; /* Verde más oscuro */
    color: #e0f2e0 !important; /* Verde claro */
}
